// A request to the agent (docs/mqtt-api.md, "Requests"): a new id every time, as the agent
// drops one it has seen. The mqtt out node sends it on fiber/cmd, never retained.
const ask = (op, params) => ({
    payload: { id: "node-red-" + Date.now() + "-" + Math.random().toString(36).slice(2, 10), op, params },
});

// Above this, in degrees Celsius, the display says which probe and how warm, and the buzzer
// sounds the alarm. Once more only after the probe was a degree below.
const LIMIT = 30;
const BELOW = LIMIT - 1;

// fiber/thermometers/<id>: {"port":3,"temperature":31.5,"ts":...}, or an empty message when the
// probe is gone (docs/mqtt-api.md).
const probe = msg.topic.split("/").pop();
const above = context.get("above") || {};
const t = msg.payload;
if (!t || typeof t !== "object") {
    delete above[probe];
} else if (t.temperature !== null && t.temperature > LIMIT && !above[probe]) {
    above[probe] = true;
    context.set("above", above);
    return [[
        ask("display.message", {
            text: "Port " + t.port + ": " + t.temperature.toFixed(1) + " °C\nabove " + LIMIT + " °C",
            seconds: 600,
        }),
        ask("buzzer.beep", { pattern: "alarm" }),
    ]];
} else if (t.temperature !== null && t.temperature < BELOW) {
    delete above[probe];
}
context.set("above", above);
return null;
